using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTests.LoyaltyDiscount;

public sealed class CalculatePayableTotalAcceptanceTests
{
    [Theory]
    [InlineData(LoyaltyTier.Green, 4_999, 4_750)]     // 5% of 4999 = 249.95 -> 249
    [InlineData(LoyaltyTier.Green, 5_000, 4_700)]     // threshold in 1-point band
    [InlineData(LoyaltyTier.Green, 10_000, 9_400)]
    [InlineData(LoyaltyTier.Green, 19_999, 18_800)]   // 6% = 1199.94 -> 1199
    [InlineData(LoyaltyTier.Green, 20_000, 18_400)]   // threshold in 3-point band
    [InlineData(LoyaltyTier.Gold, 4_999, 4_650)]      // 7% = 349.93 -> 349
    [InlineData(LoyaltyTier.Gold, 5_000, 4_600)]
    [InlineData(LoyaltyTier.Gold, 19_999, 18_400)]    // 8% = 1599.92 -> 1599
    [InlineData(LoyaltyTier.Gold, 20_000, 18_000)]    // 10, at cap
    [InlineData(LoyaltyTier.Platinum, 4_999, 4_550)]  // 9% = 449.91 -> 449
    [InlineData(LoyaltyTier.Platinum, 5_000, 4_500)]  // 10, at cap
    [InlineData(LoyaltyTier.Platinum, 20_000, 18_000)] // 12 capped to 10
    [InlineData(LoyaltyTier.Green, 0, 0)]
    public void CustomersPayTheApprovedLoyaltyTotal(LoyaltyTier tier, int subtotalCents, int expectedPayableCents)
    {
        Assert.Equal(expectedPayableCents, new CalculatePayableTotal().For(subtotalCents, tier));
    }

    [Fact]
    public void DiscountIsRoundedDownToWholeCent()
    {
        // 5% of 1 cent... 33 * 5% = 1.65 -> discount 1
        Assert.Equal(32, new CalculatePayableTotal().For(33, LoyaltyTier.Green));
    }
}
